import { ImageResponse } from "next/og";

// PWA icons, generated by code (no binary assets): the UltraVestra "UV" mark —
// bold white letters inside a glowing magenta ring on the brand black.
//   /app-icon/192      -> 192x192, purpose "any"
//   /app-icon/512      -> 512x512, purpose "any"
//   /app-icon/maskable -> 512x512, purpose "maskable" (mark kept inside the
//                         central safe zone, background stays full-bleed)
const KINDS: Record<string, { size: number; maskable: boolean }> = {
  "192": { size: 192, maskable: false },
  "512": { size: 512, maskable: false },
  maskable: { size: 512, maskable: true },
};

export async function GET(
  _request: Request,
  { params }: { params: Promise<{ kind: string }> }
) {
  const { kind } = await params;
  const entry = KINDS[kind];
  if (!entry) {
    return new Response("Not found", { status: 404 });
  }

  const { size, maskable } = entry;
  // Proportions mirror the original PIL-drawn mark (ring ~78% of canvas,
  // stroke ~5%); the maskable variant scales the whole mark down so the ring
  // and its glow stay inside the maskable safe zone.
  const ring = Math.round(size * (maskable ? 0.6 : 0.78));
  const stroke = Math.max(2, Math.round(size * (maskable ? 0.038 : 0.05)));
  const glow = Math.round(size * 0.045);
  const fontSize = Math.round(size * (maskable ? 0.26 : 0.34));

  return new ImageResponse(
    (
      <div
        style={{
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          backgroundColor: "#020008",
        }}
      >
        <div
          style={{
            width: ring,
            height: ring,
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            borderRadius: "50%",
            border: `${stroke}px solid #e879f9`,
            boxShadow: `0 0 ${glow}px #d946ef, inset 0 0 ${glow}px #d946ef`,
            color: "#ffffff",
            fontSize,
            fontWeight: 900,
            lineHeight: 1,
            letterSpacing: "-0.02em",
          }}
        >
          UV
        </div>
      </div>
    ),
    {
      width: size,
      height: size,
      headers: {
        "Cache-Control": "public, max-age=31536000, immutable",
      },
    }
  );
}
